  "It is an online workshop workflow for preparing a vehicle-specific ECU calibration from the submitted original read, exact controller identity, fuel, drivetrain and vehicle context. It is not a universal file selected only by model name.": [
    "Es handelt sich um einen Online-Workshop-Workflow zur Vorbereitung einer fahrzeugspezifischen ECU-Kalibrierung anhand der übermittelten Originaldaten, der genauen Controller-Identität, des Kraftstoffs, des Antriebsstrangs und des Fahrzeugkontexts. Es handelt sich nicht um eine universelle Datei, die nur anhand des Modellnamens ausgewählt wird.",
    "Gönderilen orijinal okumadan, tam kontrol cihazı kimliğinden, yakıttan, aktarma organlarından ve araç bağlamından araca özel bir ECU kalibrasyonu hazırlamak için çevrimiçi bir atölye iş akışıdır. Yalnızca model adına göre seçilen evrensel bir dosya değildir.",
    "Het is een online werkplaatsworkflow voor het voorbereiden van een voertuigspecifieke ECU-kalibratie op basis van de ingediende originele lezing, exacte controlleridentiteit, brandstof, aandrijflijn en voertuigcontext. Het is geen universeel bestand dat alleen op modelnaam wordt geselecteerd.",
    "Il s'agit d'un flux de travail d'atelier en ligne permettant de préparer un étalonnage ECU spécifique au véhicule à partir de la lecture originale soumise, de l'identité exacte du contrôleur, du carburant, de la transmission et du contexte du véhicule. Il ne s'agit pas d'un fichier universel sélectionné uniquement par nom de modèle.",
    "Si tratta di un flusso di lavoro di officina online per preparare una calibrazione ECU specifica per il veicolo dalla lettura originale inviata, dall'identità esatta del controller, dal carburante, dalla trasmissione e dal contesto del veicolo. Non è un file universale selezionato solo in base al nome del modello.",
    "Es un flujo de trabajo de taller en línea para preparar una calibración ECU específica del vehículo a partir de la lectura original enviada, la identidad exacta del controlador, el combustible, la transmisión y el contexto del vehículo. No es un archivo universal seleccionado únicamente por el nombre del modelo.",
    "É um fluxo de trabalho online para oficinas que permite preparar uma calibração da ECU específica do veículo a partir da leitura original enviada, da identificação exata da unidade de controlo, do combustível, da transmissão e do contexto do veículo. Não é um ficheiro universal selecionado apenas pelo nome do modelo.",
    "Jest to proces warsztatu online służący do przygotowania kalibracji ECU dla konkretnego pojazdu na podstawie przesłanego oryginalnego odczytu, dokładnej tożsamości sterownika, paliwa, układu napędowego i kontekstu pojazdu. Nie jest to plik uniwersalny, wybierany jedynie po nazwie modelu.",
    "Это рабочий процесс онлайн-мастерской для подготовки калибровки ECU для конкретного автомобиля на основе представленного оригинального считывания, точной идентификации контроллера, топлива, трансмиссии и контекста транспортного средства. Это не универсальный файл, выбранный только по названию модели.",
    "这是一个在线维修厂工作流程，根据提交的原始读取文件、准确的控制器标识、燃料类型、传动系统和车辆信息，为特定车辆准备 ECU 标定。它不是仅按车型名称选择的通用文件。",
    "Është një punëtori në internet për përgatitjen e një kalibrimi ECU specifik për automjetin nga leximi origjinal i dorëzuar, identiteti i saktë i kontrolluesit, karburanti, grupi i drejtimit dhe konteksti i automjetit. Nuk është një skedar universal i zgjedhur vetëm sipas emrit të modelit.",
  ],
