  "MG AutoTech keeps the complete workflow in the customer portal: submit the untouched original ECU file, record the read method and technical notes, follow customer-visible status, download delivered versions and request a revision when testing or logging provides useful evidence.": [
    "MG AutoTech behält den gesamten Arbeitsablauf im Kundenportal bei: Senden Sie die unberührte Originaldatei ECU, zeichnen Sie die Lesemethode und technische Hinweise auf, verfolgen Sie den für den Kunden sichtbaren Status, laden Sie gelieferte Versionen herunter und fordern Sie eine Überarbeitung an, wenn Tests oder Protokollierung nützliche Beweise liefern.",
    "MG AutoTech iş akışının tamamını müşteri portalında tutar: el değmemiş orijinal ECU dosyasını gönderin, okuma yöntemini ve teknik notları kaydedin, müşterinin görebildiği durumu takip edin, teslim edilen sürümleri indirin ve test ederken veya günlüğe kaydederken revizyon talebinde bulunun, yararlı kanıtlar sağlar.",
    "MG AutoTech bewaart de volledige workflow in het klantenportaal: dien het onaangeroerde originele ECU-bestand in, leg de leesmethode en technische opmerkingen vast, volg de voor de klant zichtbare status, download geleverde versies en vraag een revisie aan wanneer testen of loggen nuttig bewijs oplevert.",
    "MG AutoTech conserve le flux de travail complet dans le portail client : soumettez le fichier ECU original intact, enregistrez la méthode de lecture et les notes techniques, suivez l'état visible par le client, téléchargez les versions livrées et demandez une révision lorsque les tests ou la journalisation fournissent des preuves utiles.",
    "MG AutoTech mantiene il flusso di lavoro completo nel portale cliente: invia il file ECU originale intatto, registra il metodo di lettura e le note tecniche, segue lo stato visibile al cliente, scarica le versioni consegnate e richiede una revisione quando il test o la registrazione forniscono prove utili.",
    "MG AutoTech mantiene el flujo de trabajo completo en el portal del cliente: envíe el archivo ECU original intacto, registre el método leído y las notas técnicas, siga el estado visible para el cliente, descargue las versiones entregadas y solicite una revisión cuando las pruebas o el registro proporcionen evidencia útil.",
    "A MG AutoTech mantém todo o fluxo de trabalho no portal do cliente: envie o ficheiro ECU original e inalterado, registe o método de leitura e as notas técnicas, acompanhe o estado visível ao cliente, descarregue as versões entregues e peça uma revisão quando os testes ou registos fornecerem dados úteis.",
    "MG AutoTech przechowuje cały przepływ pracy w portalu klienta: prześlij nienaruszony oryginalny plik ECU, zapisz metodę odczytu i uwagi techniczne, śledź status widoczny dla klienta, pobierz dostarczone wersje i poproś o korektę, gdy testowanie lub rejestrowanie dostarczy użytecznych dowodów.",
    "MG AutoTech хранит весь рабочий процесс на клиентском портале: отправьте нетронутый исходный файл ECU, запишите метод чтения и технические примечания, отслеживайте статус, видимый для клиента, загружайте доставленные версии и запрашивайте версию, когда тестирование или регистрация предоставляют полезные доказательства.",
    "MG AutoTech在客户门户中保留完整的工作流程：提交未修改的原始ECU文件，记录读取方法和技术注释，跟踪客户可见的状态，下载交付的版本，并在测试或记录提供有用证据时请求修订。",
    "MG AutoTech ruan fluksin e plotë të punës në portalin e klientit: dorëzoni skedarin origjinal të paprekur ECU, regjistroni metodën e lexuar dhe shënimet teknike, ndiqni statusin e dukshëm nga klienti, shkarkoni versionet e dorëzuara dhe kërkoni një rishikim kur testimi ose regjistrimi ofron prova të dobishme.",
  ],
