  "Performance-oriented request paths for vehicles where the workshop needs clean notes, vehicle data and file context before review.": [
    "Leistungsorientierte Anfrageabläufe für Fahrzeuge, bei denen die Werkstatt vor der Prüfung klare Angaben, Fahrzeugdaten und Informationen zur Datei bereitstellen muss.",
    "Servisin inceleme öncesinde net notlar, araç verileri ve dosyaya ilişkin bilgiler sağlaması gereken araçlar için performans odaklı talep akışları.",
    "Prestatiegerichte aanvraagroutes voor voertuigen waarvoor de werkplaats vóór de beoordeling duidelijke notities, voertuiggegevens en bestandsinformatie moet aanleveren.",
    "Parcours de demande axés sur les performances pour les véhicules dont l’atelier doit fournir, avant examen, des notes claires, les données du véhicule et les informations relatives au fichier.",
    "Percorsi di richiesta orientati alle prestazioni per i veicoli per i quali l’officina deve fornire, prima della verifica, note chiare, dati del veicolo e informazioni sul file.",
    "Flujos de solicitud orientados al rendimiento para vehículos en los que el taller debe aportar, antes de la revisión, notas claras, datos del vehículo e información sobre el archivo.",
    "Fluxos de pedido orientados para o desempenho, para veículos em que a oficina deve fornecer, antes da análise, notas claras, dados do veículo e informações sobre o ficheiro.",
    "Ścieżki zleceń dotyczących osiągów dla pojazdów, w przypadku których warsztat przed weryfikacją musi podać jasne informacje, dane pojazdu oraz informacje o pliku.",
    "Процессы подачи заявок на повышение характеристик для автомобилей, по которым мастерская до проверки должна предоставить понятные примечания, данные автомобиля и сведения о файле.",
    "面向性能优化的请求流程，适用于维修厂在审核前需要提供清晰备注、车辆数据和文件信息的车辆。",
    "Rrjedha kërkesash të orientuara drejt performancës për automjete ku servisi, përpara shqyrtimit, duhet të japë shënime të qarta, të dhënat e automjetit dhe informacion për skedarin.",
  ],
  "Petrol and diesel engines use different control strategies, operating limits and diagnostic evidence. For that reason, the requested response and torque delivery are considered within the submitted platform instead of being described with universal power figures.": [
    "Benzin- und Dieselmotoren verwenden unterschiedliche Steuerstrategien, Betriebsgrenzen und Diagnosenachweise. Aus diesem Grund werden die angeforderte Reaktion und die Drehmomentabgabe innerhalb der eingereichten Plattform berücksichtigt, anstatt mit universellen Leistungsangaben beschrieben zu werden.",
    "Benzinli ve dizel motorlar farklı kontrol stratejileri, çalışma sınırları ve teşhis kanıtları kullanır. Bu nedenle talep edilen tepki ve tork iletimi, evrensel güç rakamlarıyla tarif edilmek yerine, sunulan platform dahilinde dikkate alınmaktadır.",
    "Benzine- en dieselmotoren gebruiken verschillende regelstrategieën, bedrijfslimieten en diagnostisch bewijsmateriaal. Om die reden wordt er rekening gehouden met de gevraagde respons en koppellevering binnen het ingediende platform in plaats van te worden beschreven met universele vermogenscijfers.",
    "Les moteurs essence et diesel utilisent des stratégies de contrôle, des limites de fonctionnement et des preuves de diagnostic différentes. Pour cette raison, la réponse demandée et la délivrance du couple sont prises en compte dans la plate-forme soumise au lieu d'être décrites avec des chiffres de puissance universels.",
    "I motori benzina e diesel utilizzano strategie di controllo, limiti operativi ed evidenze diagnostiche differenti. Per questo motivo, la risposta richiesta e l'erogazione della coppia vengono considerate all'interno della piattaforma presentata invece di essere descritte con valori di potenza universali.",
    "Los motores de gasolina y diésel utilizan diferentes estrategias de control, límites operativos y pruebas de diagnóstico. Por esa razón, la respuesta solicitada y la entrega de par se consideran dentro de la plataforma presentada en lugar de describirse con cifras de potencia universales.",
    "Os motores a gasolina e a gasóleo utilizam estratégias de controlo, limites operacionais e dados de diagnóstico diferentes. Por esse motivo, a resposta pretendida e a entrega de binário são analisadas no contexto da plataforma enviada, em vez de serem descritas através de valores de potência universais.",
    "Silniki benzynowe i wysokoprężne korzystają z różnych strategii sterowania, ograniczeń eksploatacyjnych i dowodów diagnostycznych. Z tego powodu żądana reakcja i dostarczanie momentu obrotowego są uwzględniane w ramach zgłaszanej platformy, a nie opisywane uniwersalnymi wartościami mocy.",
    "Бензиновые и дизельные двигатели используют разные стратегии управления, эксплуатационные пределы и диагностические данные. По этой причине требуемый отклик и передача крутящего момента рассматриваются в рамках представленной платформы, а не описываются универсальными показателями мощности.",
    "汽油和柴油发动机使用不同的控制策略、操作限制和诊断证据。因此，所请求的响应和扭矩传递是在提交的平台内考虑的，而不是用通用功率图来描述。",
    "Motorët me benzinë ​​dhe me naftë përdorin strategji të ndryshme kontrolli, kufij funksionimi dhe prova diagnostikuese. Për këtë arsye, përgjigja e kërkuar dhe dërgimi i çift rrotullues konsiderohen brenda platformës së paraqitur në vend që të përshkruhen me shifra universale të fuqisë.",
  ],
