  "Prepare the original file, vehicle details, engine, ECU or TCU information, read method, exact DTCs if relevant and a short workshop note.": [
    "Bereiten Sie die Originaldatei, Fahrzeugdetails, Motor-, ECU- oder TCU-Informationen, Lesemethode, ggf. die genaue DTCs und eine kurze Werkstattnotiz vor.",
    "Orijinal dosyayı, araç ayrıntılarını, motoru, ECU veya TCU bilgilerini, okuma yöntemini, gerekiyorsa tam DTCs listesini ve kısa bir atölye notunu hazırlayın.",
    "Bereid het originele bestand, de voertuiggegevens, de motor, de ECU- of TCU-informatie, de leesmethode, de exacte DTC’s indien relevant en een korte werkplaatsnotitie voor.",
    "Préparez le fichier original, les détails du véhicule, les informations sur le moteur, le ECU ou le TCU, la méthode de lecture, le DTCs exact le cas échéant et une courte note d'atelier.",
    "Preparare il file originale, i dettagli del veicolo, il motore, le informazioni su ECU o TCU, il metodo di lettura, l'esatto DTCs se pertinente e una breve nota sull'officina.",
    "Prepare el archivo original, los detalles del vehículo, el motor, la información de ECU o TCU, el método de lectura, el DTCs exacto si es relevante y una breve nota del taller.",
    "Prepare o ficheiro original, os dados do veículo e do motor, as informações da ECU ou TCU, o método de leitura, os DTC exatos, quando relevantes, e uma breve nota da oficina.",
    "Przygotuj oryginalny plik, dane pojazdu, silnik, informacje o ECU lub TCU, przeczytaj metodę, dokładny DTCs, jeśli dotyczy, oraz krótką notatkę warsztatową.",
    "Подготовьте исходный файл, данные автомобиля, двигатель, информацию ECU или TCU, метод считывания, точный DTCs, если необходимо, и краткую заметку для мастерской.",
    "准备原始文件、车辆详细信息、发动机、ECU 或 TCU 信息、阅读方法、准确的 DTCs（如果相关）以及简短的维修说明。",
    "Përgatitni skedarin origjinal, të dhënat e automjetit, motorin, informacionin e ECU-së ose TCU-së, metodën e leximit, DTC-të e sakta kur janë relevante dhe një shënim të shkurtër servisi.",
  ],
