  "Real request quality comes from the intake flow: vehicle context, original file, service scope, notes, review status and delivery all stay connected to the same customer order.": [
    "Echte Anfragequalität ergibt sich aus dem Eingangsfluss: Fahrzeugkontext, Original-Datei, Serviceumfang, Notizen, Überprüfungsstatus und Lieferung bleiben alle mit derselben Kundenbestellung verbunden.",
    "Gerçek talep kalitesi alım akışından gelir: araç içeriği, orijinal dosya, servis kapsamı, notlar, inceleme durumu ve teslimatın tümü aynı müşteri siparişine bağlı kalır.",
    "De echte vraagkwaliteit komt voort uit de intakestroom: voertuigcontext, originele bestand, serviceomvang, notities, beoordelingsstatus en levering blijven allemaal verbonden met dezelfde klantorder.",
    "La véritable qualité de la demande vient du flux d'admission : le contexte du véhicule, le fichier d'origine, l'étendue du service, les notes, l'état de l'examen et la livraison restent tous liés à la même commande client.",
    "La vera qualità della richiesta deriva dal flusso di aspirazione: il contesto del veicolo, lo file originale, l'ambito del servizio, le note, lo stato della revisione e la consegna rimangono tutti collegati allo stesso ordine del cliente.",
    "La calidad real de la solicitud proviene del flujo de admisión: el contexto del vehículo, el archivo original, el alcance del servicio, las notas, el estado de la revisión y la entrega permanecen conectados al mismo pedido del cliente.",
    "A qualidade do pedido começa na recolha de dados: o contexto do veículo, o ficheiro original, o âmbito do serviço, as notas, o estado da revisão e a entrega permanecem associados ao mesmo pedido do cliente.",
    "Prawdziwa jakość żądań wynika z przepływu danych: kontekst pojazdu, oryginał plik, zakres usług, notatki, status przeglądu i dostawa – wszystko to pozostaje powiązane z tym samym zamówieniem klienta.",
    "Реальное качество запроса зависит от потока поступления: контекст автомобиля, оригинальный файл, объем услуг, примечания, статус проверки и доставка — все это остается связанным с одним и тем же заказом клиента.",
    "真正的请求质量来自于接收流程：车辆背景、原始 文件、服务范围、注释、审核状态和交付都保持与同一客户订单相关。",
    "Cilësia reale e kërkesës vjen nga fluksi i marrjes: konteksti i automjetit, skedar origjinal, shtrirja e shërbimit, shënimet, statusi i rishikimit dhe shpërndarja, të gjitha qëndrojnë të lidhura me të njëjtin porosi klienti.",
  ],
