  "SCR / AdBlue-related requests can require more review depending on vehicle platform, ECU and diagnostic context.": [
    "SCR/AdBlue-bezogene Anfragen können je nach Fahrzeugplattform, ECU und Diagnosekontext eine weitere Prüfung erfordern.",
    "SCR / AdBlue ile ilgili talepler, araç platformuna, ECU ve teşhis bağlamına bağlı olarak daha fazla inceleme gerektirebilir.",
    "Voor SCR/AdBlue-gerelateerde verzoeken kan meer beoordeling nodig zijn, afhankelijk van het voertuigplatform, de ECU en de diagnostische context.",
    "Les demandes liées aux SCR / AdBlue peuvent nécessiter un examen plus approfondi en fonction de la plate-forme du véhicule, du ECU et du contexte de diagnostic.",
    "Le richieste relative a SCR / AdBlue possono richiedere una revisione più approfondita a seconda della piattaforma del veicolo, di ECU e del contesto diagnostico.",
    "Las solicitudes relacionadas con SCR / AdBlue pueden requerir más revisión según la plataforma del vehículo, ECU y el contexto de diagnóstico.",
    "Os pedidos relacionados com SCR / AdBlue podem exigir uma análise mais aprofundada, consoante a plataforma do veículo, a ECU e o contexto de diagnóstico.",
    "Żądania związane z SCR / AdBlue mogą wymagać dokładniejszego przeglądu w zależności od platformy pojazdu, ECU i kontekstu diagnostycznego.",
    "Запросы, связанные с SCR/AdBlue, могут потребовать дополнительной проверки в зависимости от платформы автомобиля, ECU и диагностического контекста.",
    "根据车辆平台、ECU 和诊断上下文，与 SCR / AdBlue 相关的请求可能需要更多审查。",
    "Kërkesat e lidhura me SCR / AdBlue mund të kërkojnë më shumë rishikim në varësi të platformës së automjetit, ECU dhe kontekstit diagnostik.",
  ],
  "SCR and AdBlue requirements vary by jurisdiction": [
    "Die SCR- und AdBlue-Anforderungen variieren je nach Gerichtsbarkeit",
    "SCR ve AdBlue gereksinimleri yargı yetkisine göre değişir",
    "De SCR- en AdBlue-vereisten variëren per rechtsgebied",
    "Les exigences SCR et AdBlue varient selon les juridictions",
    "I requisiti SCR e AdBlue variano in base alla giurisdizione",
    "Los requisitos de SCR y AdBlue varían según la jurisdicción",
    "Os requisitos de SCR e AdBlue variam consoante a jurisdição",
    "Wymagania SCR i AdBlue różnią się w zależności od jurysdykcji",
    "Требования SCR и AdBlue различаются в зависимости от юрисдикции.",
    "SCR 和 AdBlue 要求因司法管辖区而异",
    "Kërkesat SCR dhe AdBlue ndryshojnë sipas juridiksionit",
  ],
  "SCR or AdBlue deactivation may be restricted or prohibited for public-road use. The customer must confirm the lawful application and remains responsible for any motorsport, export, off-road, development or diagnostic use declared in the request.": [
    "Die SCR- oder AdBlue-Deaktivierung kann für den öffentlichen Straßenverkehr eingeschränkt oder verboten sein. Der Kunde muss die rechtmäßige Anwendung bestätigen und bleibt für alle in der Anfrage deklarierten Motorsport-, Export-, Offroad-, Entwicklungs- oder Diagnoseverwendungen verantwortlich.",
    "SCR veya AdBlue'nun devre dışı bırakılması kamuya açık yol kullanımında kısıtlanabilir veya yasaklanabilir. Müşteri, yasal başvuruyu onaylamalı ve talepte beyan edilen her türlü motor sporları, ihracat, off-road, geliştirme veya tanı amaçlı kullanımdan sorumlu olmaya devam etmelidir.",
    "De deactivering van SCR of AdBlue kan beperkt of verboden zijn voor gebruik op de openbare weg. De klant moet de rechtmatige aanvraag bevestigen en blijft verantwoordelijk voor elk autosport-, export-, off-road-, ontwikkelings- of diagnostisch gebruik dat in de aanvraag wordt vermeld.",
    "La désactivation du SCR ou du AdBlue peut être restreinte ou interdite pour une utilisation sur la voie publique. Le client doit confirmer l'application légale et reste responsable de toute utilisation en sport automobile, exportation, tout-terrain, développement ou diagnostic déclarée dans la demande.",
    "La disattivazione del sistema SCR o AdBlue può essere limitata o vietata per l'uso su strada pubblica. Il cliente deve confermare l'applicazione legittima e rimane responsabile per qualsiasi uso motoristico, di esportazione, fuoristrada, di sviluppo o diagnostico dichiarato nella richiesta.",
    "La desactivación de SCR o AdBlue puede estar restringida o prohibida para su uso en vías públicas. El cliente debe confirmar la aplicación legal y sigue siendo responsable de cualquier uso en deportes de motor, exportación, todoterreno, desarrollo o diagnóstico declarado en la solicitud.",
    "A desativação de SCR ou AdBlue pode ser restrita ou proibida na via pública. O cliente deve confirmar a utilização legal e continua responsável por qualquer utilização declarada no pedido para competição automóvel, exportação, fora de estrada, desenvolvimento ou diagnóstico.",
    "Dezaktywacja SCR lub AdBlue może być ograniczona lub zabroniona w przypadku użytku na drogach publicznych. Klient musi potwierdzić zgodność aplikacji z prawem i pozostaje odpowiedzialny za wszelkie zastosowania w sportach motorowych, eksporcie, zastosowaniach terenowych, pracach rozwojowych lub diagnostyce zadeklarowane we wniosku.",
    "Деактивация SCR или AdBlue может быть ограничена или запрещена для использования на дорогах общего пользования. Клиент должен подтвердить законное применение и несет ответственность за любое использование в автоспорте, экспорте, бездорожье, разработке или диагностике, заявленное в запросе.",
    "SCR 或 AdBlue 停用可能会受到限制或禁止在公共道路上使用。客户必须确认合法申请，并对请求中声明的任何赛车运动、出口、越野、开发或诊断用途负责。",
    "Çaktivizimi i SCR ose AdBlue mund të kufizohet ose ndalohet për përdorim në rrugë publike. Klienti duhet të konfirmojë aplikimin e ligjshëm dhe të mbetet përgjegjës për çdo motorsport, eksport, jashtë rrugës, zhvillim ose përdorim diagnostikues të deklaruar në kërkesë.",
  ],
