  "Transmission jobs get their own route so gearbox type, torque limits and read method do not get mixed with ECU notes.": [
    "Getriebeaufträge folgen einem eigenen Ablauf, damit Getriebetyp, Drehmomentgrenzen und Auslesemethode nicht mit ECU-Hinweisen vermischt werden.",
    "Şanzıman işleri ayrı bir akışta yürütülür; böylece şanzıman tipi, tork sınırları ve okuma yöntemi ECU notlarıyla karışmaz.",
    "Transmissieopdrachten volgen een eigen traject, zodat het type versnellingsbak, de koppellimieten en de uitleesmethode niet met ECU-notities worden vermengd.",
    "Les travaux sur la transmission suivent un parcours dédié afin que le type de boîte, les limites de couple et la méthode de lecture ne soient pas mélangés aux notes ECU.",
    "I lavori sul cambio seguono un percorso dedicato, così il tipo di cambio, i limiti di coppia e il metodo di lettura non si confondono con le note ECU.",
    "Los trabajos de la caja de cambios siguen un flujo propio para que el tipo de caja, los límites de par y el método de lectura no se mezclen con las notas de la ECU.",
    "Os trabalhos na caixa de velocidades seguem um fluxo próprio, para que o tipo de caixa, os limites de binário e o método de leitura não se misturem com as notas da ECU.",
    "Zlecenia dotyczące skrzyni biegów mają osobny przebieg, aby typ skrzyni, limity momentu obrotowego i metoda odczytu nie mieszały się z notatkami ECU.",
    "Работы с трансмиссией ведутся в отдельном процессе, чтобы тип коробки передач, ограничения крутящего момента и метод чтения не смешивались с примечаниями по ECU.",
    "变速箱项目采用独立流程，避免将变速箱类型、扭矩限制和读取方法与 ECU 备注混在一起。",
    "Punët me transmisionin ndjekin një rrjedhë të veçantë, që lloji i kutisë së shpejtësive, kufijtë e çift-rrotullimit dhe metoda e leximit të mos përzihen me shënimet e ECU-së.",
  ],
