  "Turbo, exhaust, fuel-system or other supporting changes should be declared and may require Stage 2 or custom review.": [
    "Turbo-, Auspuff-, Kraftstoffsystem- oder andere unterstützende Änderungen sollten deklariert werden und erfordern möglicherweise eine Stage 2 oder eine benutzerdefinierte Überprüfung.",
    "Turbo, egzoz, yakıt sistemi veya diğer destekleyici değişiklikler bildirilmelidir ve Stage 2 veya özel inceleme gerektirebilir.",
    "Wijzigingen aan de turbo, het uitlaatsysteem, het brandstofsysteem of andere ondersteunende wijzigingen moeten worden aangegeven en vereisen mogelijk een Stage 2 of een aangepaste beoordeling.",
    "Le turbo, l'échappement, le système de carburant ou d'autres modifications connexes doivent être déclarés et peuvent nécessiter un Stage 2 ou un examen personnalisé.",
    "Turbo, scarico, sistema di alimentazione o altre modifiche di supporto devono essere dichiarate e potrebbero richiedere Stage 2 o una revisione personalizzata.",
    "El turbo, el escape, el sistema de combustible u otros cambios de soporte deben declararse y pueden requerir Stage 2 o una revisión personalizada.",
    "As alterações no turbo, escape, sistema de combustível ou outros componentes complementares devem ser declaradas e podem exigir Stage 2 ou uma revisão personalizada.",
    "Należy zgłosić zmiany w turbosprężarce, układzie wydechowym, układzie paliwowym lub inne dodatkowe zmiany, co może wymagać przeglądu Stage 2 lub niestandardowego.",
    "Изменения турбонаддува, выхлопной системы, топливной системы или другие сопутствующие изменения должны быть заявлены и могут потребовать Stage 2 или индивидуальной проверки.",
    "涡轮、排气、燃油系统或其他支持变更应申报，并可能需要 Stage 2 或定制审查。",
    "Turbo, shkarkimi, sistemi i karburantit ose ndryshime të tjera mbështetëse duhet të deklarohen dhe mund të kërkojnë Stage 2 ose rishikim me porosi.",
  ],
