  "Upload original file": [
    "Originaldatei hochladen",
    "Orijinal dosyayı yükle",
    "Origineel bestand uploaden",
    "Téléverser le fichier d’origine",
    "Carica il file originale",
    "Subir el archivo original",
    "Carregar ficheiro original",
    "Prześlij oryginalny plik",
    "Загрузить исходный файл",
    "上传原始文件",
    "Ngarko skedarin origjinal",
  ],
  "Use the secure request flow and state the tool and OBD, bench, boot or virtual-read method. Tool name alone does not prove read coverage or originality, so the file context is still reviewed.": [
    "Nutzen Sie den sicheren Anfrageablauf und geben Sie das verwendete Tool sowie die Auslesemethode OBD, Bench, Boot oder Virtual Read an. Der Toolname allein belegt weder die Ausleseabdeckung noch die Originalität der Datei; deshalb werden die Angaben zur Datei weiterhin geprüft.",
    "Güvenli talep akışını kullanın; kullanılan cihazı ve OBD, Bench, Boot veya Virtual Read okuma yöntemini belirtin. Cihazın adı tek başına okuma kapsamını ya da dosyanın orijinalliğini kanıtlamaz; bu nedenle dosyaya ilişkin bilgiler ayrıca incelenir.",
    "Gebruik de beveiligde aanvraagprocedure en vermeld de gebruikte tool en de uitleesmethode OBD, Bench, Boot of Virtual Read. De toolnaam alleen toont niet aan welke uitlezing wordt ondersteund of dat het bestand origineel is; daarom worden de bestandsgegevens alsnog beoordeeld.",
    "Utilisez le parcours de demande sécurisé et indiquez l’outil utilisé ainsi que la méthode de lecture OBD, Bench, Boot ou Virtual Read. Le nom de l’outil ne suffit pas à prouver la couverture de lecture ni l’originalité du fichier ; les informations relatives au fichier sont donc toujours vérifiées.",
    "Utilizza il flusso di richiesta sicuro e indica lo strumento utilizzato e il metodo di lettura OBD, Bench, Boot o Virtual Read. Il solo nome dello strumento non dimostra la copertura di lettura né l’originalità del file; le informazioni sul file vengono quindi comunque verificate.",
    "Utilice el flujo de solicitud seguro e indique la herramienta utilizada y el método de lectura OBD, Bench, Boot o Virtual Read. El nombre de la herramienta por sí solo no demuestra la cobertura de lectura ni la originalidad del archivo; por eso también se revisa la información del archivo.",
    "Utilize o fluxo de pedido seguro e indique a ferramenta utilizada e o método de leitura OBD, Bench, Boot ou Virtual Read. O nome da ferramenta, por si só, não comprova a cobertura de leitura nem a originalidade do ficheiro; por isso, as informações do ficheiro continuam a ser analisadas.",
    "Skorzystaj z bezpiecznego procesu składania zlecenia i podaj użyte narzędzie oraz metodę odczytu: OBD, Bench, Boot lub Virtual Read. Sama nazwa narzędzia nie potwierdza zakresu odczytu ani oryginalności pliku, dlatego informacje o pliku są również weryfikowane.",
    "Используйте безопасный процесс подачи заявки и укажите используемый инструмент и метод чтения: OBD, Bench, Boot или Virtual Read. Одного названия инструмента недостаточно, чтобы подтвердить полноту считывания или оригинальность файла, поэтому сведения о файле также проверяются.",
    "请使用安全请求流程，并注明所用工具以及 OBD、Bench、Boot 或 Virtual Read 读取方式。仅凭工具名称无法证明读取支持范围或文件原创性，因此仍会审核文件相关信息。",
    "Përdorni rrjedhën e sigurt të kërkesës dhe tregoni pajisjen e përdorur dhe metodën e leximit OBD, Bench, Boot ose Virtual Read. Vetëm emri i pajisjes nuk dëshmon mbulimin e leximit apo origjinalitetin e skedarit; prandaj informacioni për skedarin shqyrtohet gjithsesi.",
  ],
