  "Workshops often need more than one simple category. MG AutoTech separates performance, aftertreatment, diagnostics, TCU, function requests and support add-ons so the request can be prepared clearly.": [
    "Werkstätten benötigen oft mehr als eine einzelne Kategorie. MG AutoTech gliedert Anfragen in Leistungssteigerung, Abgasnachbehandlung, Diagnose, TCU, Funktionswünsche und zusätzliche Supportleistungen, damit sie eindeutig vorbereitet werden können.",
    "Servislerin ihtiyaçları çoğu zaman tek bir basit kategoriyle sınırlı değildir. MG AutoTech; talebin açık biçimde hazırlanabilmesi için performans, egzoz sonrası arıtma, arıza teşhisi, TCU, fonksiyon talepleri ve ek destek seçeneklerini ayrı başlıklarda sunar.",
    "Werkplaatsen hebben vaak meer nodig dan één eenvoudige categorie. MG AutoTech verdeelt aanvragen over prestaties, uitlaatgasnabehandeling, diagnose, TCU, functieverzoeken en aanvullende ondersteuning, zodat ze duidelijk kunnen worden voorbereid.",
    "Les ateliers ont souvent besoin de plus d’une simple catégorie. MG AutoTech sépare les demandes liées aux performances, au post-traitement, au diagnostic, au TCU et aux fonctions, ainsi que les options d’assistance, afin de les préparer clairement.",
    "Le officine spesso hanno bisogno di più di una semplice categoria. MG AutoTech suddivide le richieste in prestazioni, post-trattamento, diagnostica, TCU, funzioni e servizi di supporto aggiuntivi, così da prepararle in modo chiaro.",
    "Los talleres suelen necesitar más de una categoría sencilla. MG AutoTech organiza las solicitudes por rendimiento, postratamiento, diagnóstico, TCU y funciones, además de opciones de asistencia adicionales, para prepararlas con claridad.",
    "As oficinas precisam frequentemente de mais do que uma única categoria. A MG AutoTech organiza os pedidos por desempenho, pós-tratamento, diagnóstico, TCU e funções, além de opções adicionais de apoio, para os preparar com clareza.",
    "Warsztaty często potrzebują więcej niż jednej prostej kategorii. MG AutoTech dzieli zlecenia na dotyczące osiągów, układu oczyszczania spalin, diagnostyki, TCU i funkcji oraz na dodatkowe opcje wsparcia, aby można je było jasno przygotować.",
    "Мастерским часто требуется больше, чем одна простая категория. MG AutoTech разделяет запросы по повышению характеристик, системам доочистки выхлопных газов, диагностике, TCU и функциям, а также дополнительные услуги поддержки, чтобы заявку можно было четко подготовить.",
    "维修厂的需求通常不止一个简单类别。MG AutoTech 将性能、尾气后处理、诊断、TCU、功能请求和附加支持服务分开，便于清晰准备请求。",
    "Serviseve shpesh u nevojitet më shumë se një kategori e thjeshtë. MG AutoTech i ndan kërkesat sipas performancës, pastrajtimit të gazrave, diagnostikimit, TCU-së dhe funksioneve, si edhe sipas shërbimeve shtesë të mbështetjes, në mënyrë që ato të përgatiten qartë.",
  ],
