  "Verify source history, controller identity and read coverage before another calibration is considered.": [
    "Prüfen Sie den Verlauf der Quelldatei, die Steuergeräteidentifikation und den Ausleseumfang, bevor eine weitere Kalibrierung in Betracht gezogen wird.",
    "Başka bir kalibrasyon değerlendirilmeden önce kaynak dosyanın geçmişini, kontrol ünitesi tanımlama bilgilerini ve okuma kapsamını doğrulayın.",
    "Controleer de geschiedenis van het bronbestand, de controlleridentificatie en de leesdekking voordat een andere kalibratie wordt overwogen.",
    "Vérifiez l’historique du fichier source, l’identification du calculateur et l’étendue de la lecture avant d’envisager une autre calibration.",
    "Verificare la cronologia del file sorgente, l’identificazione della centralina e la copertura della lettura prima di valutare un’altra calibrazione.",
    "Verifique el historial del archivo de origen, la identificación de la unidad de control y la cobertura de lectura antes de considerar otra calibración.",
    "Verifique o histórico do ficheiro de origem, a identificação da unidade de controlo e a cobertura da leitura antes de considerar outra calibração.",
    "Przed rozważeniem kolejnej kalibracji sprawdź historię pliku źródłowego, identyfikację sterownika i zakres odczytu.",
    "Перед рассмотрением другой калибровки проверьте историю исходного файла, идентификационные данные блока управления и полноту считывания.",
    "在考虑其他标定之前，请核实源文件历史、控制器识别信息和读取范围。",
    "Verifikoni historikun e skedarit burimor, identifikimin e njësisë së kontrollit dhe mbulimin e leximit përpara se të merret në konsideratë një kalibrim tjetër.",
  ],
