  "Use brand guides for vehicle-specific intake context; exact support is confirmed from the submitted ECU or TCU identity.": [
    "Nutzen Sie die Markenleitfäden für fahrzeugspezifische Angaben zur Anfrage; die genaue Unterstützung wird anhand der übermittelten ECU- oder TCU-Identifikation bestätigt.", "Araca özgü talep bilgileri için marka rehberlerini kullanın; kesin destek, gönderilen ECU veya TCU tanımlama bilgileri üzerinden doğrulanır.", "Gebruik de merkgidsen voor voertuigspecifieke aanvraaggegevens; exacte ondersteuning wordt bevestigd aan de hand van de ingediende ECU- of TCU-identificatie.", "Utilisez les guides par marque pour fournir les informations propres au véhicule lors de la demande ; la prise en charge exacte est confirmée à partir de l’identification ECU ou TCU transmise.", "Utilizzare le guide per marca per fornire le informazioni specifiche del veicolo nella richiesta; il supporto esatto viene confermato in base all’identificazione ECU o TCU inviata.", "Utilice las guías de marca para aportar los datos específicos del vehículo en la solicitud; la compatibilidad exacta se confirma a partir de la identificación ECU o TCU enviada.", "Utilize os guias por marca para fornecer os dados específicos do veículo no pedido; o suporte exato é confirmado a partir da identificação ECU ou TCU enviada.", "Skorzystaj z przewodników po markach, aby podać w zgłoszeniu informacje właściwe dla pojazdu; dokładna obsługa jest potwierdzana na podstawie przesłanej identyfikacji ECU lub TCU.", "Используйте руководства по маркам, чтобы указать в запросе данные конкретного автомобиля; точная поддержка подтверждается по переданным идентификационным данным ECU или TCU.", "使用品牌指南提供车辆特定的请求信息；具体支持情况将根据提交的 ECU 或 TCU 识别信息确认。", "Përdorni udhëzuesit e markave për të dhënat specifike të automjetit në kërkesë; mbështetja e saktë konfirmohet nga identifikimi i dorëzuar i ECU ose TCU.",
  ],
