  "Use the BMW guide for engine, gearbox, ECU identity and read-method context before opening the request.": [
    "Nutzen Sie vor dem Erstellen der Anfrage den BMW-Leitfaden für Angaben zu Motor, Getriebe, ECU-Identifikation und Auslesemethode.", "Talebi açmadan önce motor, şanzıman, ECU tanımlama bilgileri ve okuma yöntemi ayrıntıları için BMW rehberini kullanın.", "Gebruik vóór het openen van de aanvraag de BMW-gids voor informatie over motor, versnellingsbak, ECU-identificatie en leesmethode.", "Avant d’ouvrir la demande, utilisez le guide BMW pour les informations sur le moteur, la boîte de vitesses, l’identification ECU et la méthode de lecture.", "Prima di aprire la richiesta, utilizzare la guida BMW per le informazioni su motore, cambio, identificazione ECU e metodo di lettura.", "Antes de abrir la solicitud, utilice la guía BMW para la información sobre motor, caja de cambios, identificación ECU y método de lectura.", "Antes de abrir o pedido, utilize o guia BMW para as informações sobre motor, caixa de velocidades, identificação ECU e método de leitura.", "Przed utworzeniem zlecenia skorzystaj z przewodnika BMW, aby podać dane silnika, skrzyni biegów, identyfikację ECU i metodę odczytu.", "Перед созданием запроса воспользуйтесь руководством BMW для указания двигателя, коробки передач, идентификации ECU и способа чтения.", "创建请求前，请使用 BMW 指南填写发动机、变速箱、ECU 识别信息和读取方式。", "Përpara hapjes së kërkesës, përdorni udhëzuesin BMW për të dhënat e motorit, kutisë së shpejtësive, identifikimin e ECU dhe metodën e leximit.",
  ],
