    "Nutzen Sie die Leitfäden zu Steuergerätefamilien, wenn die Suche beim ECU-Hersteller oder der Plattform statt beim Fahrzeugmodell beginnt.", "Arama araç modeli yerine ECU tedarikçisi veya platformla başlıyorsa kontrol ünitesi ailesi rehberlerini kullanın.", "Gebruik de gidsen voor controllerfamilies wanneer de zoekopdracht begint met de ECU-leverancier of het platform in plaats van het voertuigmodel.", "Utilisez les guides par famille de calculateurs lorsque la recherche commence par le fournisseur de l’ECU ou la plateforme plutôt que par le modèle du véhicule.", "Utilizzare le guide delle famiglie di centraline quando la ricerca parte dal fornitore dell’ECU o dalla piattaforma anziché dal modello del veicolo.", "Utilice las guías de familias de unidades de control cuando la búsqueda comience por el proveedor de la ECU o la plataforma en lugar del modelo del vehículo.", "Utilize os guias das famílias de unidades de controlo quando a pesquisa começa pelo fornecedor da ECU ou pela plataforma, em vez do modelo do veículo.", "Skorzystaj z przewodników po rodzinach sterowników, gdy wyszukiwanie zaczyna się od dostawcy ECU lub platformy, a nie od modelu pojazdu.", "Используйте руководства по семействам блоков управления, если поиск начинается с производителя ECU или платформы, а не с модели автомобиля.", "当搜索以 ECU 供应商或平台而非车型为起点时，请使用控制器系列指南。", "Përdorni udhëzuesit e familjeve të njësive të kontrollit kur kërkimi nis nga furnizuesi i ECU ose platforma dhe jo nga modeli i automjetit.",
