  "Hardware-aware calibration for a modified vehicle. The exact installed parts, ECU identity and drivetrain context must be documented before review.": [
    "An die Hardware angepasste Kalibrierung für ein modifiziertes Fahrzeug. Die exakt verbauten Teile, die ECU-Identifikation und der Antriebsstrang müssen vor der Prüfung dokumentiert werden.", "Modifiye bir araç için donanıma uyarlanmış kalibrasyon. İncelemeden önce takılı parçalar, ECU tanımlama bilgileri ve aktarma sistemi ayrıntıları eksiksiz belgelenmelidir.", "Op de hardware afgestemde kalibratie voor een aangepast voertuig. De exact gemonteerde onderdelen, ECU-identificatie en aandrijflijnconfiguratie moeten vóór beoordeling worden gedocumenteerd.", "Calibration tenant compte du matériel d’un véhicule modifié. Les pièces exactement installées, l’identification de l’ECU et la configuration de la chaîne cinématique doivent être documentées avant l’examen.", "Calibrazione adattata all’hardware di un veicolo modificato. Prima della verifica devono essere documentati i componenti installati, l’identificazione ECU e la configurazione della catena cinematica.", "Calibración adaptada al hardware de un vehículo modificado. Antes de la revisión deben documentarse los componentes instalados, la identificación de la ECU y la configuración de la cadena cinemática.", "Calibração adaptada ao hardware de um veículo modificado. Antes da análise, devem ser documentados os componentes instalados, a identificação da ECU e a configuração do grupo motopropulsor.", "Kalibracja uwzględniająca osprzęt zmodyfikowanego pojazdu. Przed weryfikacją należy dokładnie udokumentować zamontowane części, identyfikację ECU i konfigurację układu napędowego.", "Калибровка с учётом оборудования модифицированного автомобиля. До проверки необходимо точно задокументировать установленные компоненты, идентификацию ECU и конфигурацию силовой передачи.", "针对改装车辆硬件进行适配调校。审核前必须准确记录已安装部件、ECU 识别信息和动力系统配置。", "Kalibrim i përshtatur me pajisjet e një automjeti të modifikuar. Para shqyrtimit duhet të dokumentohen saktë pjesët e instaluara, identifikimi i ECU-së dhe konfigurimi i grupit të transmetimit.",
  ],
